        const wrong = [P.fmt(x, n + 1), P.fmt(x, n - 1 || 1), String(Math.round(x * 100) / 100)].filter((w) => w !== right);
        return { kind: "wr", template: "sigfig", sig: `sf|${x}|${n}`, stem: L(`A calculator shows ${x} for a time in seconds.`, `Une calculatrice affiche ${x} pour une durée en secondes.`, `Una calculadora muestra ${x} para un tiempo en segundos.`, `Ein Taschenrechner zeigt ${x} für eine Zeit in Sekunden.`, `计算器显示时间为 ${x} 秒。`),
          parts: [pmc(r, "a", fill(L("Rounded to {n} significant figures it is…", "Arrondi à {n} chiffres significatifs, cela donne…", "Redondeado a {n} cifras significativas es…", "Auf {n} signifikante Stellen gerundet ist das…", "保留 {n} 位有效数字为……"), { n }), same(right), [...new Set(wrong)].slice(0, 3).map((w) => ({ t: same(w), why: { key: "ph.note.round", cat: "numerical" } })), { skills: ["units"] })],
          hints: [L("Count from the first non-zero digit.", "Comptez à partir du premier chiffre non nul.", "Cuenta desde la primera cifra distinta de cero.", "Zähle ab der ersten Ziffer ungleich null.", "从第一个非零数字开始数。")], solution: [same(right)] };
